/// <summary>
/// HSMobileOpsCountStageSvc's answer: the stock count and the counter's staging journal, how many lines were
/// accepted, how many items in the stock count are counted more than once and not yet decided, and
/// (getStageMode) whether counts against counting journals in the store go to the control center.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountStageResponse
{
    boolean     success;
    str         errorCode;
    str         message;
    str         masterId;
    str         stageId;
    int         accepted;
    int         duplicates;
    boolean     stageJournalCounts;
    str         masterType;
    int         rejected;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('MasterId')]
public str parmMasterId(str _value = masterId)
{
    masterId = _value;
    return masterId;
}

[DataMemberAttribute('StageId')]
public str parmStageId(str _value = stageId)
{
    stageId = _value;
    return stageId;
}

[DataMemberAttribute('Accepted')]
public int parmAccepted(int _value = accepted)
{
    accepted = _value;
    return accepted;
}

[DataMemberAttribute('Duplicates')]
public int parmDuplicates(int _value = duplicates)
{
    duplicates = _value;
    return duplicates;
}

[DataMemberAttribute('StageJournalCounts')]
public boolean parmStageJournalCounts(boolean _value = stageJournalCounts)
{
    stageJournalCounts = _value;
    return stageJournalCounts;
}

[DataMemberAttribute('MasterType')]
public str parmMasterType(str _value = masterType)
{
    masterType = _value;
    return masterType;
}

[DataMemberAttribute('Rejected')]
public int parmRejected(int _value = rejected)
{
    rejected = _value;
    return rejected;
}
